            var dFcs = deltaA.fcs + deltaB.fcs;
            var dBvs = deltaA.bvs + deltaB.bvs;
            var dSli = deltaA.sli + deltaB.sli;

            state.domainState.gqi = this._clamp(state.domainState.gqi + dGqi, 0, 25);
            state.domainState.fcs = this._clamp(state.domainState.fcs + dFcs, 0, 25);
            state.domainState.bvs = this._clamp(state.domainState.bvs + dBvs, 0, 25);
            state.domainState.sli = this._clamp(state.domainState.sli + dSli, 0, 25);

            var total = state.domainState.gqi + state.domainState.fcs + state.domainState.bvs + state.domainState.sli;

            state.domainState.gqiHistory.push(state.domainState.gqi);
            state.domainState.fcsHistory.push(state.domainState.fcs);
            state.domainState.bvsHistory.push(state.domainState.bvs);
            state.domainState.sliHistory.push(state.domainState.sli);
            state.domainState.totalHistory.push(total);

            // v1.1.0: prevent double-submit re-entrancy (double-applied deltas / duplicated
            // history rows). Disable submit now; _updateBriefing re-enables when next round renders.
            var _submitBtn = document.getElementById('nextPeriodBtn');
            if (_submitBtn) { _submitBtn.disabled = true; }

            this._renderRoundFeedback(round, dGqi, dFcs, dBvs, dSli, total, state.decisions.legacyText || '');

            // platform score: total is already the 0-100 sum of the four dimensions getPerformanceSummary reports as the final verdict, so reuse it directly, clamped
            var overallScore = Math.max(0, Math.min(100, Math.round(total)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var self = this;
            var nextPeriod = round + 1;
            if (nextPeriod <= (state.maxPeriods || 5)) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: nextPeriod });
                }, 500);
            }

            return {
                period: round,
                decisionA: dA,
                decisionB: dB,
                deltaGqi: dGqi,
                deltaFcs: dFcs,
                deltaBvs: dBvs,
                deltaSli: dSli,
                gqi: state.domainState.gqi,
                fcs: state.domainState.fcs,
                bvs: state.domainState.bvs,
                sli: state.domainState.sli,
                total: total,
                legacyText: state.decisions.legacyText || ''
            };
        }

