            uiManager.bind('gqiDisplay', 'domainState.gqi', function(v) { return Math.round(v) + ' / 25'; });
            uiManager.bind('fcsDisplay', 'domainState.fcs', function(v) { return Math.round(v) + ' / 25'; });
            uiManager.bind('bvsDisplay', 'domainState.bvs', function(v) { return Math.round(v) + ' / 25'; });
