        getPerformanceSummary(history) {
            if (!history.length) return {};

            var last = history[history.length - 1];
            var r = last.results || {};
            var total = (r.gqi || 0) + (r.fcs || 0) + (r.bvs || 0) + (r.sli || 0);

            var performance = 'At Risk';
            if (total >= 85) performance = 'Excellent';
            else if (total >= 70) performance = 'Good';
            else if (total >= 55) performance = 'Adequate';

            var insights = [];
            if (r.gqi < 12) insights.push('Governance structures were underinvested. Consider strengthening Board oversight and Family Protocol.');
            if (r.fcs < 12) insights.push('Family cohesion suffered. More inclusive processes and transparent communication could help.');
            if (r.bvs < 12) insights.push('Business viability is fragile. More decisive strategic action may be needed.');
            if (r.sli < 12) insights.push('Succession legitimacy is low. Fair, transparent processes build stronger leadership mandates.');
            if (total >= 85) insights.push('Outstanding governance design. The Montoya Group is well-positioned for multi-generational success.');

            return {
                totalScore: total,
                gqi: r.gqi,
                fcs: r.fcs,
                bvs: r.bvs,
                sli: r.sli,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var total = results.total || 0;
            var round = results.period || 0;

            if (results.deltaFcs < -2) return window.mySimulation.t('hint_family_tension');
            if (results.deltaGqi < 0) return window.mySimulation.t('hint_weak_governance');
            if (round >= 3 && results.bvs < 8) return window.mySimulation.t('hint_business_risk');
            if (total >= 70 && round >= 4) return window.mySimulation.t('hint_strong_position');
            return null;
        }

